from pathlib import Path
import json,numpy as np
from exoplanet.pipeline import sha,save_json,read_curve,now
from exoplanet.search import flatten
from exoplanet.followup import fixed_measure
p=Path(__file__).parent;plan=json.loads((p/'plan.json').read_text());r=json.loads((p/'results.json').read_text());prior=Path('results/followup-469309982-20261011');assert sha(prior/'frozen.json')==plan['prior_frozen_sha256'] and sha(prior/'heldout.json')==plan['sector64_sha256'];h=json.loads((prior/'heldout.json').read_text());f=json.loads((prior/'frozen.json').read_text());assert plan['clocks'][0]['best']=={**f['best'],'period':h['profile_best']['period'],'transit_time':h['profile_best']['epoch']};assert plan['clocks'][1]['best']==f['best'];raw=Path('data/lightcurves/s0063-469309982.fits');assert sha(raw)==r['source']['sha256'] and plan['created_utc']<r['source']['retrieved_utc'];t,y,e,star=read_curve(raw);assert star['ticid']==469309982 and star['sector']==63;t,y,e=flatten(t,y,e)
for c,saved in zip(plan['clocks'],r['rows']):
 b=c['best'];assert saved['best']==b and saved['name']==c['name'];m=fixed_measure(t,y,e,b['period'],b['transit_time'],b['duration']);assert m==saved['measurement'];total=m['total'];expected=None if total is None else b['depth']/total['error'];result='insufficient_coverage' if total is None else 'fixed_clock_recovery_requires_source_vetting' if total['snr']>=5 and m['supported_events']>=2 else 'not_recovered_despite_expected_sensitivity' if expected>=5 and total['snr']<2 else 'insufficient_evidence';assert result==saved['screening_result'] and expected==saved['expected_formal_snr']
z=np.load(p/'photometry.npz');np.testing.assert_array_equal(t,z['time']);np.testing.assert_array_equal(y,z['flux']);np.testing.assert_array_equal(e,z['error']);save_json(p/'verification.json',dict(status='passed',verified_utc=now(),plan_precedes_download=True,clock_matches_sector64_selection=True,raw_hash_and_identity_checked=True,two_fixed_clock_measurements_reproduced=True,limits='Conditional reproducibility, not physical confirmation or false-alarm calibration.'))
